import Foundation
import Testing
@testable import VelaMedia

/// Checks the adult-domain list that ships in VelaMedia's resources
/// (generated by scripts/update-adult-domains.sh) and the loader that reads it.
@Suite struct BundledAdultListTests {
    /// The repository root, found from this file's location so the tests can
    /// read the source copy of the list and the exclude list.
    private static let repoRoot = URL(filePath: #filePath)
        .deletingLastPathComponent() // VelaMediaTests
        .deletingLastPathComponent() // Tests
        .deletingLastPathComponent() // VelaKit
        .deletingLastPathComponent() // Packages
        .deletingLastPathComponent()

    private static let sourceList = repoRoot
        .appending(path: "Packages/VelaKit/Sources/VelaMedia/Resources/adult-domains.txt")

    private static func lines(of url: URL) throws -> [String] {
        try String(contentsOf: url, encoding: .utf8)
            .split(separator: "\n", omittingEmptySubsequences: false)
            .map(String.init)
    }

    // MARK: - The bundled list

    @Test func bundledListIsLarge() {
        #expect(AdultSiteList.bundled.count >= 10_000)
    }

    @Test func bundledCountMatchesTheHeader() throws {
        let prefix = "# Domains:"
        let header = try #require(try Self.lines(of: Self.sourceList).first { $0.hasPrefix(prefix) })
        let declared = try #require(Int(header.dropFirst(prefix.count).trimmingCharacters(in: .whitespaces)))
        #expect(AdultSiteList.bundled.count == declared)
    }

    @Test(arguments: ["pornhub.com", "xvideos.com", "xhamster.com", "chaturbate.com", "redtube.com"])
    func knownAdultDomainsMatch(domain: String) {
        let list = AdultSiteList.bundled
        #expect(list.contains(host: domain))
        #expect(list.contains(host: "www.\(domain)"))
        #expect(list.contains(host: "cdn.media.\(domain)"))
    }

    @Test func unrelatedHostsDoNotMatch() {
        let list = AdultSiteList.bundled
        #expect(!list.contains(host: "example.com"))
        #expect(!list.contains(host: "www.example.com"))
        // Matching is on label boundaries, never on substrings.
        #expect(!list.contains(host: "notpornhub.com"))
        #expect(!list.contains(host: "pornhub.com.example.org"))
        #expect(!list.contains(host: "xvideos.community"))
    }

    @Test func excludedPlatformsNeverMatch() throws {
        let excluded = try Self.lines(of: Self.repoRoot.appending(path: "scripts/adult-domains-exclude.txt"))
            .map { line in line.prefix { $0 != "#" }.trimmingCharacters(in: .whitespaces) }
            .filter { !$0.isEmpty }
        #expect(excluded.count > 50)
        let list = AdultSiteList.bundled
        for host in excluded {
            #expect(!list.contains(host: host), "\(host) is on the exclude list")
            #expect(!list.contains(host: "www.\(host)"), "www.\(host) is on the exclude list")
        }
    }

    @Test(arguments: [
        "i.imgur.com", "pbs.twimg.com", "i.redd.it", "media.tenor.com",
        "upload.wikimedia.org", "raw.githubusercontent.com", "cdn.discordapp.com",
    ])
    func everydayMediaHostsDoNotMatch(host: String) {
        #expect(!AdultSiteList.bundled.contains(host: host))
    }

    // MARK: - Loading a list file

    @Test func loadsAListFile() throws {
        let url = FileManager.default.temporaryDirectory
            .appending(path: "adult-domains-\(UUID().uuidString).txt")
        defer { try? FileManager.default.removeItem(at: url) }
        try """
        # A test list.
        # Domains: 2
        #
        adult.example
        nsfw.example.org

        """.write(to: url, atomically: true, encoding: .utf8)

        let list = try AdultSiteList(contentsOf: url)
        #expect(list.count == 2)
        #expect(list.contains(host: "adult.example"))
        #expect(list.contains(host: "img.adult.example"))
        #expect(list.contains(host: "nsfw.example.org"))
        #expect(list.contains(host: "a.b.nsfw.example.org"))
        // A listed subdomain doesn't block its parent or its siblings.
        #expect(!list.contains(host: "example.org"))
        #expect(!list.contains(host: "www.example.org"))
        #expect(!list.contains(host: "notadult.example"))
        #expect(!list.contains(host: "adult.example.net"))
    }

    @Test func sourceFileMatchesTheBundledList() throws {
        let fromSource = try AdultSiteList(contentsOf: Self.sourceList)
        #expect(fromSource.count == AdultSiteList.bundled.count)
    }
}
